CREATE TABLE IF NOT EXISTS market_candle_quotes (instrument text NOT NULL REFERENCES instruments(code), timeframe text NOT NULL, close_time timestamptz NOT NULL, bid_open numeric NOT NULL, bid_high numeric NOT NULL, bid_low numeric NOT NULL, bid_close numeric NOT NULL, ask_open numeric NOT NULL, ask_high numeric NOT NULL, ask_low numeric NOT NULL, ask_close numeric NOT NULL, source text NOT NULL CHECK(source='oanda'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(instrument,timeframe,close_time,source));
